// The three maps. Geometry lives in ./maps/*.json (generated by `npm run maps`)
// and is loaded lazily so the first paint only pulls the map you're looking at.
export const MAPS = [
  {
    id: 'world',
    key: 'w',
    tiny: 0.0045, // places smaller than this share of the map width get a marker
    label: 'World',
    unit: ['country', 'countries'],
    posterUnit: ['country', 'countries'],
    posterPlace: 'around the world',
    load: () => import('./maps/world.json'),
    // world regions carry `w` = share of the world's land area
    stat: (visited, regions) => {
      const share = regions.reduce((s, r) => s + (visited.has(r.id) ? r.w : 0), 0)
      return { value: `${share < 0.01 && share > 0 ? '<1' : Math.round(share * 100)}%`, label: 'of the world’s land' }
    },
  },
  {
    id: 'india',
    key: 'i',
    tiny: 0.014,
    label: 'India',
    unit: ['state', 'states & UTs'],
    posterUnit: ['state', 'states & UTs'],
    posterPlace: 'across India',
    load: () => import('./maps/india.json'),
    stat: (visited, regions) => ({ value: `${Math.round((visited.size / regions.length) * 100)}%`, label: 'of India' }),
  },
  {
    id: 'usa',
    key: 'u',
    tiny: 0.014,
    label: 'USA',
    unit: ['state', 'states'],
    posterUnit: ['state', 'states'],
    posterPlace: 'across the USA',
    load: () => import('./maps/usa.json'),
    stat: (visited, regions) => ({ value: `${Math.round((visited.size / regions.length) * 100)}%`, label: 'of the USA' }),
  },
]

export const getMap = (id) => MAPS.find((m) => m.id === id) ?? MAPS[0]
